/* ==================== ГЛАВА 5: АЛГОРИТМЫ, ЗАДАЧИ, ТЕСТ ==================== */
const ALGOS5 = [
{name:'Алгоритм С. Определить тип превращения аминокислоты', steps:[
 'Посмотрите, что ушло из молекулы. Ушла <b>аминогруппа</b> — это трансаминирование или дезаминирование.',
 'Аминогруппа <b>переехала на кетокислоту</b>, аммиака нет → трансаминирование. Аминогруппа <b>ушла как NH₃</b> → дезаминирование.',
 'Ушла <b>карбоксильная группа</b> и выделился CO₂ → декарбоксилирование, получился биогенный амин.',
 'Изменился только радикал → специфический путь (например, гидроксилирование фенилаланина).',
 '<b>Пример.</b> Глутамат → ГАМК + CO₂: ушёл углекислый газ, значит декарбоксилирование, продукт — биогенный амин.']},

{name:'Алгоритм Т. Разобрать энзимопатию обмена аминокислот', steps:[
 'Найдите заблокированный фермент и напишите реакцию, которую он катализирует.',
 'Скажите, что накапливается <b>перед</b> блоком и чего не хватает <b>после</b> него.',
 'Проверьте обходной путь: куда пойдёт накопившийся субстрат (при ФКУ — в фенилпируват).',
 'Свяжите накопление и дефицит с симптомами, назовите болезнь и диету.',
 '<b>Пример.</b> Нет фенилаланингидроксилазы → копится фенилаланин, нет тирозина → фенилпируват и фениллактат в моче, страдает синтез нейромедиаторов → фенилкетонурия, диета без фенилаланина.']},

{name:'Алгоритм У. Проследить путь аммиака', steps:[
 'Определите, где аммиак образовался: мышца, мозг, кишечник, распад нуклеотидов.',
 'Свяжите его временно: в тканях — <b>глутамин</b> (глутаминсинтетаза), в мышце — <b>аланин</b> (глюкозо-аланиновый цикл).',
 'Довезите до места обезвреживания: печень или почки.',
 'Обезвредьте окончательно: в печени — <b>мочевина</b> (орнитиновый цикл), в почках — <b>аммонийные соли</b>.',
 '<b>Пример.</b> Работающая мышца: пируват + глутамат → аланин → кровь → печень → аланин отдаёт NH₃ → мочевина, а пируват идёт в глюконеогенез.']},

{name:'Алгоритм Ф. Оценить азотистый обмен по анализам', steps:[
 'Азотистый баланс: поступило больше — положительный (рост, беременность, выздоровление); вывелось больше — отрицательный (голод, старость, болезнь).',
 'Мочевина крови ниже нормы → проверьте печень и возраст (у грудных детей на 8–10 % меньше).',
 'Мочевина и остаточный азот выше 35 ммоль/л → азотемия: продукционная (усилен распад белка) или ретенционная (почки не выводят).',
 'Аммиак выше нормы → проверьте орнитиновый цикл: генетический дефект, поражение печени или ОРВИ.',
 '<b>Пример.</b> Диета без треонина → незаменимой аминокислоты нет → синтез белка невозможен → распад преобладает → отрицательный азотистый баланс.']}
];

const TASKS5 = [
{n:'Задача 1 · учебник', algo:'Алгоритм Ф · азотистый баланс',
 q:'Здоровых крыс длительное время содержали на искусственной белковой диете, исключающей треонин и метионин. Дайте характеристику азотистого баланса. Изменится ли азотистый баланс у этих животных? Если изменится, то как и почему?',
 steps:['Определите, к какой группе относятся треонин и метионин.','Вспомните правило о недостатке одной незаменимой аминокислоты.','Сделайте вывод о соотношении синтеза и распада белка.'],
 sol:`<p><b>Треонин и метионин — незаменимые аминокислоты</b>: они не синтезируются в организме и должны поступать с пищей.</p>
 <p><b>Баланс изменится: станет отрицательным.</b> Синтез белка возможен только при наличии полного набора аминокислот. Недостаток в пище хотя бы одной незаменимой аминокислоты ведёт к <b>неполному усвоению всех остальных</b>: они не могут быть включены в белок и подвергаются дезаминированию, а их азот выводится в виде мочевины.</p>
 <p>В результате азота выводится больше, чем поступает, — процессы распада собственных белков (плазмы крови и мышц) преобладают над синтезом. Это то же состояние, что при белковой недостаточности, голодании и тяжёлых заболеваниях. Дополнительно пострадает синтез производных метионина: <b>S-аденозилметионина</b> — главного донора метильных групп, а значит, и креатина, и обезвреживания биогенных аминов.</p>`},

{n:'Задача 2 · учебник', algo:'Алгоритм У · орнитиновый цикл',
 q:'У детей вирус гриппа нередко нарушает синтез фермента карбамоилфосфатсинтетазы. При этом возникает рвота, головокружение, судороги, возможна потеря сознания. Укажите: 1) функционирование какого процесса нарушено; 2) концентрация какого вещества повышается в крови; 3) механизм его токсического действия на нервную систему; 4) какую диету можно рекомендовать.',
 steps:['Назовите процесс, первую реакцию которого катализирует этот фермент.','Скажите, что накопится перед блоком.','Разберите четыре механизма токсичности.','Предложите диету.'],
 sol:`<p><b>1) Нарушен орнитиновый цикл</b> — синтез мочевины в печени. Карбамоилфосфатсинтетаза I катализирует его первую реакцию: NH<sub>3</sub> + CO<sub>2</sub> + 2АТФ → карбамоилфосфат.</p>
 <p><b>2) Повышается концентрация аммиака</b> — развивается гипераммониемия. У детей она особенно опасна: нормы и так выше взрослых (у новорождённых 64–107 мкмоль/л против 11–32), а симптомы появляются при превышении верхней границы в 2–3 раза.</p>
 <p><b>3) Механизм токсического действия:</b></p>
 <ul>
 <li>аммиак сдвигает pH в щелочную сторону — развивается <b>алкалоз</b>;</li>
 <li>в обратной глутаматдегидрогеназной реакции α-кетоглутарат уходит в глутамат, цикл Кребса лишается субстрата — <b>гипоэнергетическое состояние</b> мозга;</li>
 <li>глутамат превращается в осмотически активный <b>глутамин</b>, жидкость накапливается в клетках мозга — угроза <b>отёка</b>;</li>
 <li>недостаток глутамата нарушает синтез нейромедиаторов, прежде всего <b>ГАМК</b>.</li>
 </ul>
 <p>Отсюда рвота, головокружение, судороги, потеря сознания.</p>
 <p><b>4) Диета — малобелковая</b>, с введением кетоаналогов аминокислот, плюс средства, стимулирующие выведение аммиака в обход нарушенных реакций.</p>`},

{n:'Задача 3 · учебник', algo:'Алгоритм Т · энзимопатия',
 q:'У ребёнка выявлено повышенное содержание фенилаланина в крови и повышенное содержание фенилпирувата в моче. Какой патологией обусловлены такие результаты? Назовите причину заболевания, напишите блокированную реакцию и схему альтернативного пути метаболизма субстрата.',
 steps:['Назовите болезнь по сочетанию «фенилаланин в крови + фенилпируват в моче».','Напишите заблокированную реакцию с ферментом и кофакторами.','Опишите обходной путь и его продукты.'],
 sol:`<p><b>Заболевание — фенилкетонурия</b>, энзимопатия обмена фенилаланина.</p>
 <p><b>Причина</b> — нарушение активности фермента <b>фенилаланингидроксилазы</b>. Блокирована реакция:</p>
 <p style="text-align:center"><b>Фенилаланин + O<sub>2</sub> + H<sub>4</sub>БП → тирозин + H<sub>2</sub>O</b> (кофакторы — тетрагидробиоптерин и Fe<sup>2+</sup>, реакция необратима)</p>
 <p><b>Альтернативный (минорный) путь.</b> В норме по нему идёт лишь около 10 % фенилаланина, при ФКУ — практически весь:</p>
 <p style="text-align:center">фенилаланин + α-кетоглутарат → <b>фенилпируват</b> → <b>фениллактат</b> и <b>фенилацетат</b> → <b>фенилацетилглутамин</b></p>
 <p>Первая стадия — трансаминирование с α-кетоглутаратом (кофактор пиридоксальфосфат). В крови и моче накапливаются фенилаланин, фениллактат и фенилацетилглутамин.</p>
 <p><b>Почему страдает мозг:</b> фенилаланин, фенилпируват и фениллактат в высоких концентрациях токсичны; кроме того, избыток фенилаланина нарушает транспорт <b>тирозина и триптофана</b> через гематоэнцефалический барьер, из-за чего падает синтез дофамина, норадреналина и серотонина. Клинически — задержка умственного и физического развития, судороги, гипопигментация, «мышиный» запах мочи. Лечение — диета с ограничением фенилаланина, расширение только после 18 лет.</p>`},

{n:'Задача 4 · учебник', algo:'Алгоритм Т · энзимопатия',
 q:'У новорождённого ребёнка обнаружили на мокрых пелёнках тёмные пятна. Биохимический анализ мочи показал большую концентрацию гомогентизиновой кислоты. Обмен какой аминокислоты нарушен? Назовите заболевание и напишите схему соответствующего процесса.',
 steps:['По названию накопившегося метаболита определите путь.','Назовите фермент, который не работает.','Напишите весь путь и объясните тёмные пятна.'],
 sol:`<p><b>Нарушен обмен тирозина</b> в печени. Заболевание — <b>алкаптонурия</b>, «чёрная моча».</p>
 <p><b>Дефектный фермент — диоксигеназа гомогентизиновой кислоты</b> (кофактор Fe<sup>2+</sup>), которая в норме расщепляет ароматическое кольцо гомогентизиновой кислоты.</p>
 <p><b>Схема катаболизма тирозина в печени:</b></p>
 <p style="text-align:center">тирозин → (тирозинаминотрансфераза, ПФ) → <b>п-гидроксифенилпируват</b> → (п-гидроксифенилпируват-диоксигеназа; витамин C, Fe<sup>2+</sup>) → <b>гомогентизиновая кислота</b> → <b>✕ блок</b> → фумарилацетоацетат → (фумарилацетоацетатгидролаза) → фумарат + ацетоацетат → цикл Кребса → CO<sub>2</sub> и H<sub>2</sub>O</p>
 <p><b>Почему тёмные пятна.</b> Гомогентизиновая кислота не превращается дальше, накапливается в крови и выводится с мочой. На воздухе она окисляется и образует тёмные пигменты — <b>алкаптоны</b>, отсюда потемнение мочи и пятна на пелёнках.</p>
 <p><b>Другие проявления:</b> пигментация соединительной ткани (<b>охроноз</b>) и артрит.</p>`},

{n:'Задача 5 · учебник', algo:'Оксид азота',
 q:'При лечении ишемической болезни сердца применяют нитроглицерин. На чём основан его лечебный эффект? Концентрация какого вещества возрастает в организме в результате приёма? Перечислите все биологические свойства этого соединения.',
 steps:['Назовите вещество, донором которого служит нитроглицерин.','Объясните механизм сосудистого эффекта.','Перечислите остальные функции этого соединения.'],
 sol:`<p>Нитроглицерин — донор <b>оксида азота (NO)</b>; в организме возрастает именно его концентрация.</p>
 <p><b>Механизм лечебного эффекта.</b> NO использует <b>гуанилатциклазный</b> путь передачи сигнала: активируется гуанилатциклаза, растёт цГМФ, активируется протеинкиназа G, фосфорилируются белки гладкомышечных клеток сосудов. Мускулатура расслабляется, просвет сосудов расширяется, кровоток через миокард улучшается — ишемия и боль уменьшаются.</p>
 <p><b>Все биологические свойства NO:</b></p>
 <ol>
 <li>расширяет просвет сосудов за счёт расслабления гладкой мускулатуры — эндотелиальный фактор релаксации;</li>
 <li>препятствует агрегации тромбоцитов;</li>
 <li>увеличивает синтез простагландинов, активируя циклооксигеназу, и через это регулирует тонус сосудов и воспаление;</li>
 <li>служит нейромедиатором, участвует в формировании памяти;</li>
 <li>обладает прооксидантным или антиоксидантным действием в зависимости от концентрации;</li>
 <li>оказывает цитотоксическое действие (апоптоз, предотвращение роста опухолей), ингибируя ферменты с гемом — аконитазу и цитохромы дыхательной цепи, что снижает синтез АТФ.</li>
 </ol>
 <p>Образуется NO из <b>аргинина</b> при участии NO-синтазы с образованием цитруллина.</p>`},

{n:'Задача 6 · для самопроверки', algo:'Алгоритм У · транспорт аммиака',
 q:'Спортсмен интенсивно работает мышцами. Проследите путь аминогруппы аминокислот из мышцы до мочевины и объясните, почему при этом не развивается лактоацидоз.',
 steps:['Назовите реакцию в мышце и её фермент.','Проследите путь переносчика в печень.','Опишите, что происходит с обеими частями молекулы в печени.'],
 sol:`<p><b>В мышце.</b> В ходе гликолиза образуется пируват. Аминокислоты отдают аминогруппы на α-кетоглутарат (трансаминирование), образуется глутамат, а затем аминогруппа переносится на пируват под действием <b>АЛТ</b> — получается <b>аланин</b>. Часть аммиака связывается также в <b>глутамин</b> глутаминсинтетазой.</p>
 <p><b>Транспорт.</b> Аланин и глутамин — основные транспортные формы азота; в крови, оттекающей от работающей мышцы, они составляют около <b>50 %</b> всех аминокислот.</p>
 <p><b>В печени.</b> Аланин подвергается непрямому дезаминированию: трансаминирование с α-кетоглутаратом даёт глутамат, глутаматдегидрогеназа освобождает <b>аммиак</b>, который идёт в орнитиновый цикл на синтез мочевины. Оставшийся <b>пируват</b> вступает в глюконеогенез, глюкоза возвращается в мышцу — это и есть <b>глюкозо-аланиновый цикл</b>.</p>
 <p><b>Почему нет лактоацидоза.</b> Пируват в мышце уходит не в лактат, а в аланин. Тем самым цикл одновременно вывозит азот и предотвращает накопление молочной кислоты.</p>`},

{n:'Задача 7 · для самопроверки', algo:'Ферментная диагностика',
 q:'У двух пациентов повышены аминотрансферазы. У первого АСТ/АЛТ = 0,6, у второго — 2,1. Предположите локализацию поражения и объясните, на чём основан вывод.',
 steps:['Вспомните норму коэффициента де Ритиса.','Вспомните, в каком органе какого фермента больше.','Сделайте вывод по каждому пациенту.'],
 sol:`<p><b>Коэффициент де Ритиса</b> — отношение активностей АСТ/АЛТ, в норме <b>1,33 ± 0,42</b>.</p>
 <p><b>Первый пациент (0,6)</b> — коэффициент снижен, преобладает АЛТ. Активность АЛТ выше в ткани <b>печени</b>, поэтому речь о поражении печени, характерно для <b>гепатитов</b>.</p>
 <p><b>Второй пациент (2,1)</b> — коэффициент повышен, преобладает АСТ. Активность АСТ выше в <b>миокарде</b>, что типично для <b>инфаркта миокарда</b>.</p>
 <p><b>Почему это работает.</b> Обе аминотрансферазы — внутриклеточные ферменты, в норме их активность в тканях значительно выше, чем в крови. При разрушении клеток или повышении проницаемости мембран ферменты выходят в кровь в той пропорции, в какой они содержались в органе. Поэтому информативно измерять оба фермента одновременно.</p>
 <p>У новорождённых умеренно повышенная АСТ (но не выше 70 ЕД/л) — вариант нормы из-за повышенной проницаемости мембран; нормализуется после 6 месяцев.</p>`},

{n:'Задача 8 · для самопроверки', algo:'Алгоритм С · биогенные амины',
 q:'У пациентки после употребления выдержанного сыра и красного вина возникают головная боль, покраснение лица, зуд и заложенность носа. Аллергологическое обследование отрицательное. Объясните биохимический механизм.',
 steps:['Назовите биогенный амин, которым богаты такие продукты.','Назовите фермент, который должен его обезвреживать.','Перечислите эффекты этого амина и причины дефицита фермента.'],
 sol:`<p>Речь о <b>пищевой непереносимости гистамина</b> — состоянии, которое возникает при недостаточной инактивации гистамина из-за <b>дефицита диаминоксидазы (ДАО)</b>.</p>
 <p><b>Механизм.</b> В норме гистамин обезвреживается двумя путями: метилированием с участием S-аденозилметионина и окислительным дезаминированием под действием ДАО (кофактор пиридоксальфосфат). При дефиците ДАО поступивший с пищей гистамин не разрушается и действует как медиатор: расширяет сосуды (покраснение лица), повышает проницаемость капилляров (отёчность, заложенность носа), раздражает нервные окончания (зуд, головная боль), стимулирует секрецию желудочного сока.</p>
 <p>Аллергические пробы отрицательные, потому что иммунного механизма нет — это не аллергия, а <b>ферментативная недостаточность</b>.</p>
 <p><b>Причины снижения активности ДАО:</b> генетическая предрасположенность; заболевания ЖКТ — воспалительные заболевания кишечника, болезнь Крона, язвенный колит, инфекции, паразитарные инвазии, мальабсорбция, дисбактериоз; болезни печени, гепатиты, цирроз; алкоголь, ряд медикаментов и другие биогенные амины; дефицит кофакторов — витаминов B<sub>6</sub> и C, меди и цинка.</p>`},

{n:'Задача 9 · для самопроверки', algo:'Алгоритм Ф · остаточный азот',
 q:'У двух пациентов остаточный азот крови равен 45 ммоль/л. У первого при этом резко повышена мочевина и снижен диурез, у второго мочевина нормальная, но много свободных аминокислот на фоне обширных ожогов. Определите тип азотемии у каждого.',
 steps:['Вспомните норму остаточного азота и порог азотемии.','Вспомните два типа абсолютной азотемии.','Соотнесите с составом остаточного азота у каждого пациента.'],
 sol:`<p>В норме остаточный азот составляет <b>14–28 ммоль/л</b>, значения выше <b>35 ммоль/л</b> расцениваются как <b>азотемия</b>. У обоих пациентов она есть.</p>
 <p><b>Первый пациент — ретенционная азотемия почечного происхождения.</b> Азотсодержащие продукты образуются нормально, но не выводятся: снижен диурез, растёт мочевина, которая в норме составляет около 50 % остаточного азота. Ретенционная азотемия может быть и <b>внепочечной</b> — при недостаточности кровоснабжения почек и снижении клубочковой фильтрации из-за декомпенсации сердечно-сосудистой деятельности.</p>
 <p><b>Второй пациент — продукционная азотемия.</b> При обширных ожогах идёт усиленный распад тканевых белков, в кровь поступает избыток азотсодержащих продуктов, прежде всего свободных аминокислот (в норме их доля 25 %). Выделительная функция почек при этом сохранна, поэтому мочевина не повышена.</p>
 <p>Отдельно существует <b>относительная</b> азотемия — при обезвоживании, когда концентрация растёт без истинного накопления.</p>`},

{n:'Задача 10 · для самопроверки', algo:'Алгоритм С · креатин',
 q:'В моче ребёнка 2 лет обнаружен креатин. Мать встревожена. Объясните, требуется ли обследование, и в каких случаях креатинурия является патологической.',
 steps:['Вспомните, что такое креатинурия и почему она возникает.','Назовите физиологические варианты.','Назовите патологические варианты и что при них смотрят.'],
 sol:`<p><b>Креатинурия</b> — появление креатина в моче; развивается, когда синтез креатина опережает возможности его фиксации в мышечной ткани.</p>
 <p><b>У ребёнка 2 лет это физиологическое явление.</b> Креатинурия отмечается от момента рождения до полового созревания: синтез креатина опережает рост и развитие мышечной массы. Отношение азота креатина к общему азоту мочи закономерно снижается с 0,7–0,8 % в первые дни жизни до 0,3–0,4 % к году. Обследование не требуется.</p>
 <p><b>Физиологической</b> считают также креатинурию <b>пожилого возраста</b> — следствие атрофии мышц и неполного использования креатина, который синтезируется в печени.</p>
 <p><b>Патологическая креатинурия</b> с наибольшими концентрациями креатина наблюдается при заболеваниях мышечной системы — <b>миопатии и прогрессирующей мышечной дистрофии</b>. В этих случаях дополнительно смотрят активность креатинкиназы: изоформа <b>MM</b> повышается при повреждении скелетных мышц (норма общей КФК — не более 90 МЕ/л).</p>`}
];

